import asyncio
import functools
import inspect
from asyncio import iscoroutinefunction
from functools import partial

def is_coroutine_callable_fixed(call):
    if call is None:
        return False

    curr = call
    while True:
        if iscoroutinefunction(curr):
            return True

        if isinstance(curr, partial):
            curr = curr.func
        elif hasattr(curr, "__wrapped__"):
            curr = curr.__wrapped__
        elif hasattr(curr, "__call__"):
            # Check __call__
            dunder_call = getattr(curr, "__call__")
            if iscoroutinefunction(dunder_call):
                return True
            # If it's a class, we stop.
            if inspect.isclass(curr):
                break
            # Otherwise, we can't unwrap further.
            break
        else:
            break
    return False

# Test cases
def sync_func(): return 1
async def async_func(): return 1

@functools.wraps(sync_func)
async def async_wrapper(f): return f()

@functools.wraps(async_func)
def sync_wrapper(f): return f()

p_async = partial(async_func)
p_sync = partial(sync_func)

@functools.wraps(p_sync)
async def async_wrapper_partial(f): return f()

p_async_wrapper = partial(async_wrapper, sync_func)

